<td class="sticky left-0 z-10 border-r border-ink-100 bg-white px-4 py-3 font-semibold text-ink-600 dark:border-ink-800 dark:bg-ink-900 dark:text-ink-300">{{ $row['label'] }}@if ($row['caption'])<span class="block text-[10px] font-medium text-ink-400 dark:text-ink-500">{{ $row['caption'] }}</span>@endif</td>
