    <td class="border-r border-ink-100 px-3 py-3 text-center text-amber-700 dark:border-ink-800 dark:text-amber-300"><x-matrix-number :value="$row['summary']['in_review']" :title="'In Review — '.$row['label']" :filters="array_merge($matrixScopeFilters, $row['filters'], ['metric' => 'in_review'])"/></td>
    <td class="border-r border-ink-100 px-3 py-3 text-center text-emerald-700 dark:border-ink-800 dark:text-emerald-300"><x-matrix-number :value="$row['summary']['complete']" :title="'Complete — '.$row['label']" :filters="array_merge($matrixScopeFilters, $row['filters'], ['metric' => 'complete'])"/></td>
    <td class="px-3 py-3 text-center"><x-matrix-number :value="$row['summary']['percentage']" suffix="%" :title="'Complete — '.$row['label']" :filters="array_merge($matrixScopeFilters, $row['filters'], ['metric' => 'complete'])" class="rounded-full px-2.5 py-1 text-[10px] {{ $row['summary']['percentage'] === 100 ? 'bg-emerald-50 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-300' : 'bg-ink-50 text-ink-600 dark:bg-ink-800 dark:text-ink-300' }}"/></td>
